import{a as e,c as t,i as n,t as r}from"./app-B8uz0aqq.js";var i=JSON.parse(`{"path":"/22-Attribute_IDL_Plan.html","title":"属性与 IDL 统一方案","lang":"en-US","frontmatter":{},"filePathRelative":"22-Attribute_IDL_Plan.md","git":{"createdTime":1765122408000,"updatedTime":1765122408000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"}]}}`),a={name:`22-Attribute_IDL_Plan.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="属性与-idl-统一方案" tabindex="-1"><a class="header-anchor" href="#属性与-idl-统一方案"><span>属性与 IDL 统一方案</span></a></h1><blockquote><p>目的：建立 Apollo 属性/消息 ID 的统一来源，确保 C++/Lua/数据库/客户端/BI 各模块共享同一套定义，避免重复和漂移。</p></blockquote><h2 id="_1-目标" tabindex="-1"><a class="header-anchor" href="#_1-目标"><span>1. 目标</span></a></h2><ol><li><strong>单一源头</strong>：所有属性、消息 ID、枚举在一份配置（Excel/YAML/Proto）中定义，自动生成多语言代码。</li><li><strong>多端同步</strong>：生成 C++ 头文件、Lua 表、Protobuf ID、数据库字段、BI 字典。</li><li><strong>可扩展性</strong>：新增属性/消息可在配置中追加，不影响旧数据。</li><li><strong>元数据</strong>：记录属性的标记（同步、持久化、广播）、默认值、描述。</li></ol><h2 id="_2-属性定义方案" tabindex="-1"><a class="header-anchor" href="#_2-属性定义方案"><span>2. 属性定义方案</span></a></h2><h3 id="_2-1-数据源" tabindex="-1"><a class="header-anchor" href="#_2-1-数据源"><span>2.1 数据源</span></a></h3><ul><li>主配置：<code>config/excel/AttributeConfig.xlsx</code> 或 YAML/JSON。</li><li>每条属性字段示例： <table><thead><tr><th>字段</th><th>含义</th></tr></thead><tbody><tr><td><code>AttrId</code></td><td>唯一 ID</td></tr><tr><td><code>Name</code></td><td>文本名称</td></tr><tr><td><code>Category</code></td><td>Basic/Combat/Element/Status...</td></tr><tr><td><code>Type</code></td><td>int32/int64/float/bool/string</td></tr><tr><td><code>Flags</code></td><td>Bitmask（DB/Guild/Gate/AOI/Sync/Broadcast…）</td></tr><tr><td><code>DefaultValue</code></td><td>默认值</td></tr><tr><td><code>Description</code></td><td>注释</td></tr></tbody></table></li></ul><h3 id="_2-2-生成目标" tabindex="-1"><a class="header-anchor" href="#_2-2-生成目标"><span>2.2 生成目标</span></a></h3><ul><li><code>AttributeIds.h</code>（C++ 枚举 + 元数据结构）</li><li><code>Attribute.lua</code>（供服务器 Lua/脚本使用）</li><li><code>attribute.proto</code>（proto 中定义 <code>enum AttributeId</code>）</li><li><code>db_attribute_map.json</code>（BI/数据库用于映射列/字段）</li><li>文档 (<code>Attribute.md</code>) 自动生成表格。</li></ul><h3 id="_2-3-工具链" tabindex="-1"><a class="header-anchor" href="#_2-3-工具链"><span>2.3 工具链</span></a></h3><ul><li>步骤：Excel → Python/Go 工具解析 → 生成文件。</li><li>校验：工具检查 ID 唯一、Flag 合法、类型匹配。</li><li>集成：在构建流程中自动执行（如 <code>cmake --build</code> 前执行脚本）。</li></ul><h2 id="_3-消息-id-proto" tabindex="-1"><a class="header-anchor" href="#_3-消息-id-proto"><span>3. 消息 ID / Proto</span></a></h2><h3 id="_3-1-结构" tabindex="-1"><a class="header-anchor" href="#_3-1-结构"><span>3.1 结构</span></a></h3><ul><li>在 <code>Tool/pb/message_registry.yaml</code> 维护消息 ID → Proto 映射：<div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code class="language-yaml"><span class="line"><span class="token key atrule">messages</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token punctuation">-</span> <span class="token key atrule">id</span><span class="token punctuation">:</span> <span class="token number">1001</span></span>
<span class="line">    <span class="token key atrule">name</span><span class="token punctuation">:</span> PlayerMove</span>
<span class="line">    <span class="token key atrule">proto</span><span class="token punctuation">:</span> fugumessage/player_move.proto</span>
<span class="line">    <span class="token key atrule">reliable</span><span class="token punctuation">:</span> <span class="token boolean important">true</span></span>
<span class="line">    <span class="token key atrule">websocket</span><span class="token punctuation">:</span> <span class="token boolean important">true</span></span>
<span class="line">    <span class="token key atrule">broadcast_flags</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token string">&quot;AOI&quot;</span><span class="token punctuation">]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li>生成 <code>MessageId.h</code>、<code>message_id.lua</code>、<code>message_id.ts</code> 等。</li></ul><h3 id="_3-2-生成流程" tabindex="-1"><a class="header-anchor" href="#_3-2-生成流程"><span>3.2 生成流程</span></a></h3><ul><li>工具读取 YAML → 解析 Proto → 验证消息是否包含 <code>MSG_ID</code> 常量。</li><li>与 NetCore/MessageDispatcher 自动对接。</li></ul><h2 id="_4-bi-数据同步" tabindex="-1"><a class="header-anchor" href="#_4-bi-数据同步"><span>4. BI/数据同步</span></a></h2><ul><li>为 BI 输出版生成 <code>attr_dict.csv</code>（字段名称、ID、类型、含义），供数据仓库使用。</li><li>DataProxy 在写 DB/TLog 时采用同一份属性字典，确保 ETL 与实时数据一致。</li></ul><h2 id="_5-版本与发布" tabindex="-1"><a class="header-anchor" href="#_5-版本与发布"><span>5. 版本与发布</span></a></h2><ul><li>属性/消息定义版本化（Git 管理），每次修改需审查（检查单、自动测试）。</li><li>SDK 与服务端版本需同步（定义文件的 hash/版本号写入构建产物）。</li><li>自动生成 CHANGELOG（新增/修改属性/消息 ID）。</li></ul><h2 id="_6-roadmap" tabindex="-1"><a class="header-anchor" href="#_6-roadmap"><span>6. Roadmap</span></a></h2><ol><li>选择单一格式（Excel + YAML）并整理现有属性列表。</li><li>编写解析/生成工具，生成 C++/Lua/proto 等文件，替换手写枚举。</li><li>整合到构建流程，每次构建前自动验证属性/消息定义。</li><li>提供文档/可视化工具展示属性/消息 ID（用于调试、运营）。</li><li>将 DataProxy/BI/TLog 等模块改为引用统一字典。</li></ol><hr><p>通过该方案，属性和消息 ID 将不再散落在多份文档中，而由单一源头控制，减少维护成本并提高一致性。***</p>`,24)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};